"""Generalized file and repository artifact classifier.

Classifies files into distinct categories:
- SOURCE: normal handwritten application source code
- TEST: test suites, mocks, and fixtures
- GENERATED: code generated by tools, compilers, protobuf, openapi, or marked DO NOT EDIT
- BUILD_ARTIFACT: build output directories (dist, build, target, .next, coverage)
- BUNDLE: bundled assets, webpack/rollup/esbuild runtime bundles
- MINIFIED: minified JavaScript, CSS, or single-line compressed assets
- VENDOR: external third-party dependencies (node_modules, vendor, venv)
- CONFIG: project, build, and dependency lockfiles
- BINARY: compiled objects, images, archives, executables
- UNKNOWN: unclassified files
"""
from __future__ import annotations

import fnmatch
import re
import sqlite3
from dataclasses import dataclass
from enum import StrEnum
from pathlib import Path
from typing import Any

